    // ---- Spacing (font "space" provider) ----------------------------------
    public static final String NEG_1 = "\uF801";
    public static final String NEG_2 = "\uF802";
    public static final String NEG_4 = "\uF803";
    public static final String NEG_8 = "\uF804";
    public static final String NEG_16 = "\uF805";
    public static final String NEG_32 = "\uF806";
    public static final String NEG_64 = "\uF807";
    public static final String NEG_128 = "\uF808";
    public static final String NEG_256 = "\uF809";
    public static final String POS_1 = "\uF821";
    public static final String POS_2 = "\uF822";
    public static final String POS_4 = "\uF823";
    public static final String POS_8 = "\uF824";
    public static final String POS_16 = "\uF825";
    public static final String POS_32 = "\uF826";
    public static final String POS_64 = "\uF827";
    public static final String POS_128 = "\uF828";
    public static final String POS_256 = "\uF829";

    /** Pixel-precise horizontal shift (negative = move left). Any value, built from powers of two. */
    public static String space(int px) {
        if (px == 0) return "";
        StringBuilder sb = new StringBuilder();
        boolean neg = px < 0;
        int left = Math.abs(px);
        int[] steps = {256, 128, 64, 32, 16, 8, 4, 2, 1};
        String[] negs = {NEG_256, NEG_128, NEG_64, NEG_32, NEG_16, NEG_8, NEG_4, NEG_2, NEG_1};
        String[] poss = {POS_256, POS_128, POS_64, POS_32, POS_16, POS_8, POS_4, POS_2, POS_1};
        for (int i = 0; i < steps.length; i++) {
            while (left >= steps[i]) { sb.append(neg ? negs[i] : poss[i]); left -= steps[i]; }
        }
        return sb.toString();
    }

