    /**
     * Container title that paints a custom background behind a chest menu.
     * Result: "\u00a7f" + space(-8) + background + space(-(GUI_ADVANCE - 8)) + "\u00a7f" + label.
     * The \u00a7f keeps the background from being tinted by the default dark-grey title colour.
     * Use with Bukkit.createInventory(holder, GUI_x_SIZE, guiTitle(GUI_x, "Label")).
     */
    public static String guiTitle(String background, String label) {
        return "\u00a7f" + space(-8) + background + space(-(GUI_ADVANCE - 8)) + "\u00a7f" + label;
    }

