    /** Medal for a 1-based placement (1..3), otherwise empty. */
    public static String medal(int place) {
        return switch (place) { case 1 -> MEDAL_1; case 2 -> MEDAL_2; case 3 -> MEDAL_3; default -> ""; };
    }

    // ---- Title bar helper -------------------------------------------------
    public static final int TITLE_BAR_WIDTH = 119;  // drawn width (advance - 1)

    /** Approximate vanilla default-font width of a string (ignores \u00a7 codes, honours \u00a7l). */
    public static int textWidth(String s) {
        int w = 0; boolean bold = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\u00a7' && i + 1 < s.length()) {
                char k = Character.toLowerCase(s.charAt(++i));
                if (k == 'l') bold = true; else if (k == 'r' || "0123456789abcdef".indexOf(k) >= 0) bold = false;
                continue;
            }
            int a = switch (c) {
                case '!', '\'', ',', '.', ':', ';', 'i', '|' -> 2;
                case '`', 'l' -> 3;
                case ' ', '"', '(', ')', '*', 'I', '[', ']', 't', '{', '}' -> 4;
                case '<', '>', 'f', 'k' -> 5;
                case '@', '~' -> 7;
                default -> c >= 0xE000 && c < 0xF900 ? 0 : 6;
            };
            w += a + (bold && a > 0 ? 1 : 0);
        }
        return w;
    }

    /** Text centred on the TITLE_BAR glyph; total advance equals the bar so vanilla centring stays exact. */
    public static String onTitleBar(String text) {
        int w = textWidth(text);
        int barAdv = TITLE_BAR_WIDTH + 1;
        int back = barAdv - (TITLE_BAR_WIDTH - w) / 2;
        int tail = barAdv - ((TITLE_BAR_WIDTH - w) / 2 + w);
        return "\u00a7f" + TITLE_BAR + space(-back) + text + space(tail);
    }

