    // ---- Pack state -------------------------------------------------------
    private static final Set<UUID> PACK_LOADED = ConcurrentHashMap.newKeySet();

    /** Call from PlayerResourcePackStatusEvent (SUCCESSFULLY_LOADED -> true, DECLINED/FAILED -> false) and on quit (false). */
    public static void setHasPack(UUID player, boolean loaded) {
        if (loaded) PACK_LOADED.add(player); else PACK_LOADED.remove(player);
    }

    public static boolean hasPack(UUID player) {
        return player != null && PACK_LOADED.contains(player);
    }

    /** glyph if the player has the pack, otherwise the plain-text fallback. */
    public static String or(UUID player, String glyph, String fallback) {
        return hasPack(player) ? glyph : fallback;
    }

    /** Sound key to use for this player (custom if pack loaded, vanilla fallback otherwise). */
    public static String sound(UUID player, String key) {
        return hasPack(player) ? key : SOUND_FALLBACK.getOrDefault(key, key);
    }
